import { expect, type APIRequestContext, type Page } from "@playwright/test";
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

/** Demo logins are generated by the provision-demo-users CLI with random passwords into tests/e2e/.auth (git-ignored). */
export function password(app: "erp" | "ai", email: string): string {
  const file = path.join(__dirname, ".auth", `${app}.logins.txt`);
  if (!fs.existsSync(file)) throw new Error(`Missing ${file}. Run scripts/e2e.ps1 so demo users are provisioned.`);
  const line = fs.readFileSync(file, "utf8").split(/\r?\n/).find((l) => l.startsWith(email + ","));
  if (!line) throw new Error(`No demo login for ${email}`);
  return line.split(",")[1];
}

export async function login(page: Page, app: "erp" | "ai", email: string, pwd = password(app, email)) {
  await page.goto("/login");
  await page.getByTestId("login-email").fill(email);
  await page.getByTestId("login-password").fill(pwd);
  await page.getByTestId("login-submit").click();
  await expect(page.getByTestId("user-name")).toBeVisible();
}

export async function logout(page: Page) {
  await page.getByTestId("logout").click();
  await expect(page).toHaveURL(/\/login/);
}

/** Bearer token for direct API checks (privilege escalation, IDOR, contention). */
export async function token(request: APIRequestContext, app: "erp" | "ai", email: string, pwd = password(app, email)): Promise<string> {
  const r = await request.post("/api/v1/auth/login", { data: { email, password: pwd } });
  expect(r.status(), await r.text()).toBe(200);
  return (await r.json()).accessToken;
}

export const bearer = (t: string) => ({ Authorization: `Bearer ${t}` });

/** Reads a value straight from the E2E database to prove a UI action was persisted (sqlcmd with Windows auth). */
export function sql(db: "SanpuErp_E2E" | "SanpuAiOps_E2E", query: string): string {
  const server = process.env.SANPU_E2E_SERVER ?? "localhost";
  return execFileSync("sqlcmd", ["-S", server, "-E", "-d", db, "-h", "-1", "-W", "-Q", `SET NOCOUNT ON; ${query}`], { encoding: "utf8" }).trim();
}

/** The page must not scroll sideways (responsive check). */
export async function expectNoHorizontalScroll(page: Page) {
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
  expect(overflow).toBeLessThanOrEqual(1);
}

/** Every visible form control has an accessible name. */
export async function expectLabelledControls(page: Page) {
  const unlabelled = await page.evaluate(() =>
    [...document.querySelectorAll("input:not([type=hidden]), select, textarea")]
      .filter((el) => (el as HTMLElement).offsetParent !== null)
      .filter((el) => {
        const id = el.getAttribute("id");
        return !(el.getAttribute("aria-label") || (id && document.querySelector(`label[for="${id}"]`)) || el.closest("label"));
      }).map((el) => el.outerHTML.slice(0, 80)));
  expect(unlabelled).toEqual([]);
}

export const unique = (prefix: string) => `${prefix}${Date.now().toString(36)}${Math.floor(Math.random() * 1e4)}`;
